 28	public sealed class PreguntarAsistente
 29	{
 30	    private readonly IApiAcademica _apiAcademica;
 31	    private readonly IClienteLlm _clienteLlm;
 32	    private readonly IBaseConocimiento _baseConocimiento;
 33	    private readonly AuditorPeticiones _auditor;
 34	    private readonly PoliticaAcceso _politicaAcceso;
 35	    private readonly LimitesAsistente _limites;
 36	    private readonly ConfiguracionAsistente _configuracion;
 37	    private readonly PresupuestoDiario _presupuesto;
 38	    private readonly LectorResumenPropio _lectorResumen;
 39	    private readonly RelevanciaPrevia _relevancia;
 40	    private readonly EmisorDeResultados _emisor;
 41	    private readonly CierreDeRespuesta _cierre;
 42	
 43	    public PreguntarAsistente(
 44	        IApiAcademica apiAcademica,
 45	        IClienteLlm clienteLlm,
 46	        IBaseConocimiento baseConocimiento,
 47	        AuditorPeticiones auditor,
 48	        PoliticaAcceso politicaAcceso,
 49	        VerificadorSalida verificadorSalida,
 50	        LimitesAsistente limites,
 51	        ConfiguracionAsistente configuracion,
 52	        PresupuestoDiario presupuesto)
 53	    {
 54	        _apiAcademica = apiAcademica;
 55	        _clienteLlm = clienteLlm;
 56	        _baseConocimiento = baseConocimiento;
 57	        _auditor = auditor;
 58	        _politicaAcceso = politicaAcceso;
 59	        _limites = limites;
 60	        _configuracion = configuracion;
 61	        _presupuesto = presupuesto;
 62	        _lectorResumen = new LectorResumenPropio(politicaAcceso);
 63	        _relevancia = new RelevanciaPrevia(politicaAcceso, configuracion.RelevanciaMinima);
 64	        _emisor = new EmisorDeResultados(auditor, politicaAcceso, configuracion);
 65	        _cierre = new CierreDeRespuesta(baseConocimiento, politicaAcceso, verificadorSalida, configuracion, _emisor);
 66	    }
 67	
 68	    public async Task<ResultadoPregunta> EjecutarAsync(
 69	        PreguntaEntrada entrada,
 70	        string ipOrigen,
 71	        string correlationId,
 72	        CancellationToken cancellationToken)
 73	    {
 74	        var presupuestoApi = TimeSpan.FromSeconds(_limites.PresupuestoApiAcademicaSegundos);
 75	        var api = new ApiAcademicaConPresupuesto(_apiAcademica, presupuestoApi);
 76	        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, api);
 77	        try
 78	        {
 79	            return await ResponderSesionAsync(sesion, cancellationToken);
 80	        }
 81	        catch (Exception)
 82	        {
 83	            _emisor.Auditar(sesion, ResultadoAuditoria.Error, null, []);
 84	            throw;
 85	        }
 86	    }
 87	
 88	    private async Task<ResultadoPregunta> ResponderSesionAsync(SesionPregunta sesion, CancellationToken cancellationToken)
 89	    {
 90	        var directorio = await ConstructorDirectorio.ConstruirAsync(sesion.Entrada.Usuario, sesion.Api, _configuracion.CodigosAsignatura, cancellationToken);
 91	        if (directorio is not null)
 92	        {
 93	            _auditor.RecordarPersonas(directorio);
 94	            sesion.Directorio = ExcluirCodigosDePersonas(directorio);
 95	        }
 96	
 97	        var decision = Autorizar(sesion);
 98	        return decision.Permitido
 99	            ? await ResponderSiEsRelevanteAsync(sesion, cancellationToken)
100	            : _emisor.Denegar(sesion, decision.Motivo, 0);
101	    }
102	
103	    private DirectorioAcademico ExcluirCodigosDePersonas(DirectorioAcademico directorio)
104	    {
105	        var catalogo = _configuracion.Catalogo;
106	        for (var indice = 0; indice < catalogo.Count; indice++)
107	        {
108	            if (CatalogoAsignaturas.EsIdDePersona(catalogo[indice].Codigo, directorio))
109	            {
110	                _configuracion.Advertir($"{Textos.PrefijoConfiguracionIgnorada}: Autorizacion:Asignaturas:{indice}:Codigo = \"{catalogo[indice].Codigo}\" (coincide con el ID de una persona del registro); se excluye del catálogo");
111	            }
112	        }
113	
114	        return directorio with { CodigosAsignatura = [.. directorio.CodigosAsignatura.Where(codigo => !CatalogoAsignaturas.EsIdDePersona(codigo, directorio))] };
115	    }
116	
117	    private async Task<ResultadoPregunta> ResponderSiEsRelevanteAsync(SesionPregunta sesion, CancellationToken cancellationToken)
118	    {
119	        var pregunta = sesion.Entrada.Pregunta;
120	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
121	        sesion.Secciones = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(pregunta), _limites.MaximoSeccionesRecuperadas);
122	        var activacion = ActivadorResumenPropio.Evaluar(contexto, pregunta, CatalogoAsignaturas.Vigente(_configuracion.Catalogo, sesion.Directorio));
123	        if (_relevancia.PeriodoNoDisponible(contexto, pregunta, activacion))
124	        {
125	            return _emisor.SinInformacion(sesion);
126	        }
127	
128	        sesion.Activacion = await _lectorResumen.VerificarMatriculaAsync(contexto, activacion, sesion.Api, sesion.Registro, cancellationToken);
129	        return _relevancia.DebeResponderSinInformacion(contexto, pregunta, sesion.Secciones, sesion.Activacion)
130	            ? _emisor.SinInformacion(sesion)
131	            : await ResponderConReservaAsync(sesion, cancellationToken);
132	    }
133	
134	    private DecisionAcceso Autorizar(SesionPregunta sesion)
135	    {
136	        var identidad = _politicaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, sesion.Directorio);
137	        return identidad.Permitido
138	            ? _politicaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, sesion.Directorio)
139	            : identidad;
140	    }
141	
142	    private async Task<ResultadoPregunta> ResponderConReservaAsync(SesionPregunta sesion, CancellationToken cancellationToken)
143	    {
144	        var reserva = _configuracion.ReservaPorPeticionUsd;
145	        if (!_presupuesto.TryReservar(reserva))
146	        {
147	            return _emisor.NoDisponible(sesion, ResultadoAuditoria.Error);
148	        }
149	
150	        sesion.ReservaHecha = true;
151	        try
152	        {
153	            return await ResponderConTimeoutAsync(sesion, cancellationToken);
154	        }
155	        finally
156	        {
157	            _presupuesto.Sustituir(reserva, _configuracion.GastoDe(sesion.Uso.Valor));
158	        }
159	    }
160	
161	    private async Task<ResultadoPregunta> ResponderConTimeoutAsync(SesionPregunta sesion, CancellationToken cancellationToken)
162	    {
163	        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
164	        limite.CancelAfter(TimeSpan.FromSeconds(_limites.TimeoutLlmSegundos));
165	        try
166	        {
167	            return await ResponderAsync(sesion, limite.Token);
168	        }
169	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
170	        {
171	            throw new DependenciaNoDisponibleException("El tiempo total de la petición se agotó.");
172	        }
173	    }
174	
175	    private async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken cancellationToken)
176	    {
177	        var usuario = sesion.Entrada.Usuario;
178	        var contexto = new ContextoUsuario(usuario, sesion.Directorio);
179	        var entrada = await PrepararEntradaAsync(sesion, contexto, cancellationToken);
180	        var conversacion = new ConversacionLlm(_clienteLlm, new HerramientasAsistente(sesion.Api, _politicaAcceso), _limites, sesion.Uso);
181	        var resultado = await conversacion.EjecutarAsync(contexto, entrada, sesion.Registro, cancellationToken);
182	        return resultado.Estado switch
183	        {
184	            EstadoConversacion.IdAjeno => _emisor.Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, sesion.Uso.Valor.Total, resultado.IdSolicitado),
185	            EstadoConversacion.LimiteHerramientas => _emisor.NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
186	            EstadoConversacion.Rechazada => _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error),
187	            _ => _cierre.Completar(sesion, resultado.Texto ?? string.Empty, entrada)
188	        };
189	    }
190	
191	    private async Task<EntradaConversacion> PrepararEntradaAsync(SesionPregunta sesion, ContextoUsuario contexto, CancellationToken cancellationToken)
192	    {
193	        var pregunta = sesion.Entrada.Pregunta;
194	        var resumen = await _lectorResumen.LeerAsync(contexto, sesion.Activacion, sesion.Api, sesion.Registro, cancellationToken);
195	        return new EntradaConversacion(pregunta, sesion.Secciones, resumen, ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario));
196	    }
197	}
