282	public enum EstadoConversacion
283	{
284	    Completada,
285	    Rechazada,
286	    LimiteHerramientas,
287	    IdAjeno
288	}
289	
290	public sealed record ResultadoConversacion(EstadoConversacion Estado, string? Texto, string? IdSolicitado = null);
291	
292	internal sealed record EntradaConversacion(
293	    string Pregunta,
294	    IReadOnlyList<SeccionDocumento> Secciones,
295	    ResumenEntregado? Resumen,
296	    string PromptSistema);
