103	    private DirectorioAcademico ExcluirCodigosDePersonas(DirectorioAcademico directorio)
104	    {
105	        var catalogo = _configuracion.Catalogo;
106	        for (var indice = 0; indice < catalogo.Count; indice++)
107	        {
108	            if (CatalogoAsignaturas.EsIdDePersona(catalogo[indice].Codigo, directorio))
109	            {
110	                _configuracion.Advertir($"{Textos.PrefijoConfiguracionIgnorada}: Autorizacion:Asignaturas:{indice}:Codigo = \"{catalogo[indice].Codigo}\" (coincide con el ID de una persona del registro); se excluye del catálogo");
111	            }
112	        }
113	
114	        return directorio with { CodigosAsignatura = [.. directorio.CodigosAsignatura.Where(codigo => !CatalogoAsignaturas.EsIdDePersona(codigo, directorio))] };
115	    }
