117	    private async Task<ResultadoPregunta> ResponderSiEsRelevanteAsync(SesionPregunta sesion, CancellationToken cancellationToken)
118	    {
119	        var pregunta = sesion.Entrada.Pregunta;
120	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
121	        sesion.Secciones = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(pregunta), _limites.MaximoSeccionesRecuperadas);
122	        var activacion = ActivadorResumenPropio.Evaluar(contexto, pregunta, CatalogoAsignaturas.Vigente(_configuracion.Catalogo, sesion.Directorio));
123	        if (_relevancia.PeriodoNoDisponible(contexto, pregunta, activacion))
124	        {
125	            return _emisor.SinInformacion(sesion);
126	        }
127	
128	        sesion.Activacion = await _lectorResumen.VerificarMatriculaAsync(contexto, activacion, sesion.Api, sesion.Registro, cancellationToken);
129	        return _relevancia.DebeResponderSinInformacion(contexto, pregunta, sesion.Secciones, sesion.Activacion)
130	            ? _emisor.SinInformacion(sesion)
131	            : await ResponderConReservaAsync(sesion, cancellationToken);
132	    }
