142	    private async Task<ResultadoPregunta> ResponderConReservaAsync(SesionPregunta sesion, CancellationToken cancellationToken)
143	    {
144	        var reserva = _configuracion.ReservaPorPeticionUsd;
145	        if (!_presupuesto.TryReservar(reserva))
146	        {
147	            return _emisor.NoDisponible(sesion, ResultadoAuditoria.Error);
148	        }
149	
150	        sesion.ReservaHecha = true;
151	        try
152	        {
153	            return await ResponderConTimeoutAsync(sesion, cancellationToken);
154	        }
155	        finally
156	        {
157	            _presupuesto.Sustituir(reserva, _configuracion.GastoDe(sesion.Uso.Valor));
158	        }
159	    }
