298	internal sealed class ConversacionLlm
299	{
300	    private readonly IClienteLlm _clienteLlm;
301	    private readonly HerramientasAsistente _herramientas;
302	    private readonly LimitesAsistente _limites;
303	    private readonly UsoAcumulado _uso;
304	
305	    public ConversacionLlm(IClienteLlm clienteLlm, HerramientasAsistente herramientas, LimitesAsistente limites, UsoAcumulado uso)
306	    {
307	        _clienteLlm = clienteLlm;
308	        _herramientas = herramientas;
309	        _limites = limites;
310	        _uso = uso;
311	    }
312	
313	    public async Task<ResultadoConversacion> EjecutarAsync(
314	        ContextoUsuario contexto,
315	        EntradaConversacion entrada,
316	        RegistroConsultas registro,
317	        CancellationToken cancellationToken)
318	    {
319	        var estado = new Turnos(
320	            contexto,
321	            registro,
322	            [ConstructorPrompts.MensajeInicial(entrada.Pregunta, entrada.Secciones, entrada.Resumen)],
323	            entrada.PromptSistema);
324	        ResultadoConversacion? final = null;
325	        while (final is null)
326	        {
327	            final = await AvanzarAsync(estado, cancellationToken);
328	        }
329	
330	        return final;
331	    }
332	
333	    private async Task<ResultadoConversacion?> AvanzarAsync(Turnos estado, CancellationToken cancellationToken)
334	    {
335	        var respuesta = await LlamarAsync(estado, cancellationToken);
336	        _uso.Sumar(respuesta.Uso);
337	        estado.Invocaciones += respuesta.Llamadas.Count;
338	        var terminal = Terminal(estado, respuesta);
339	        return terminal ?? await EjecutarHerramientasAsync(estado, respuesta, cancellationToken);
340	    }
341	
342	    private ResultadoConversacion? Terminal(Turnos estado, RespuestaLlm respuesta)
343	    {
344	        if (respuesta.Rechazada)
345	        {
346	            return new ResultadoConversacion(EstadoConversacion.Rechazada, null);
347	        }
348	
349	        if (respuesta.Llamadas.Count == 0)
350	        {
351	            return new ResultadoConversacion(EstadoConversacion.Completada, respuesta.Texto);
352	        }
353	
354	        return estado.Invocaciones > _limites.MaximoInvocacionesHerramientas
355	            ? new ResultadoConversacion(EstadoConversacion.LimiteHerramientas, null)
356	            : null;
357	    }
358	
359	    private async Task<ResultadoConversacion?> EjecutarHerramientasAsync(Turnos estado, RespuestaLlm respuesta, CancellationToken cancellationToken)
360	    {
361	        estado.Mensajes.Add(new MensajeLlm(RolMensaje.Asistente, respuesta.Texto ?? string.Empty, null, respuesta.Llamadas));
362	        foreach (var llamada in respuesta.Llamadas)
363	        {
364	            var resultado = await _herramientas.EjecutarAsync(llamada, estado.Contexto, estado.Registro, cancellationToken);
365	            if (resultado.IdAjeno)
366	            {
367	                return new ResultadoConversacion(EstadoConversacion.IdAjeno, null, resultado.IdSolicitado);
368	            }
369	
370	            estado.Registro.AgregarFuente(resultado.Contenido);
371	            estado.Mensajes.Add(new MensajeLlm(RolMensaje.Herramienta, resultado.Contenido, llamada.Id, []));
372	        }
373	
374	        return null;
375	    }
376	
377	    private async Task<RespuestaLlm> LlamarAsync(Turnos estado, CancellationToken cancellationToken)
378	    {
379	        var solicitud = new SolicitudLlm(
380	            estado.PromptSistema,
381	            [.. estado.Mensajes],
382	            HerramientasAsistente.Definir(estado.Contexto.Usuario.Rol),
383	            _limites.MaximoTokensSalida);
384	        return await _clienteLlm.CompletarAsync(solicitud, cancellationToken);
385	    }
386	
387	    private sealed class Turnos(ContextoUsuario contexto, RegistroConsultas registro, List<MensajeLlm> mensajes, string promptSistema)
388	    {
389	        public ContextoUsuario Contexto { get; } = contexto;
390	
391	        public RegistroConsultas Registro { get; } = registro;
392	
393	        public List<MensajeLlm> Mensajes { get; } = mensajes;
394	
395	        public string PromptSistema { get; } = promptSistema;
396	
397	        public int Invocaciones { get; set; }
398	    }
399	}
