412	    private readonly HashSet<string> _documentosDerogados = new HashSet<string> { DocumentoDerogado };
413	    private readonly Regex _numero = Numero();
414	    private readonly Regex _notaOPorcentaje = NotaOPorcentaje();
415	    private readonly Func<string, string> _normalizar = NormalizadorTexto.Normalizar;
416	
417	    public SalidaVerificada Verificar(
418	        Usuario usuario,
419	        string respuesta,
420	        IReadOnlyList<Cita> citas,
421	        IReadOnlyCollection<string> idsPersonasAutorizadas,
422	        IReadOnlyCollection<string> textosFuente,
423	        IBaseConocimiento baseConocimiento,
424	        DirectorioAcademico directorio,
425	        MaterialConfidencial? confidencial = null) =>
426	        RechazoPorPersona(usuario, respuesta, idsPersonasAutorizadas, directorio)
427	        ?? RechazoPorConfiguracion(respuesta, textosFuente, confidencial)
428	        ?? RechazoPorValorMonetario(respuesta, textosFuente)
429	        ?? RechazoPorNumero(respuesta, textosFuente)
430	        ?? new SalidaVerificada(respuesta, DescartarCitasInexistentes(citas, baseConocimiento), ResultadoAuditoria.Respondida);
431	
432	    private SalidaVerificada? RechazoPorPersona(
433	        Usuario usuario,
434	        string respuesta,
435	        IReadOnlyCollection<string> idsPersonasAutorizadas,
436	        DirectorioAcademico directorio) =>
437	        ContienePersonaNoAutorizada(respuesta, idsPersonasAutorizadas, directorio)
438	            ? new SalidaVerificada(Textos.Negativa(usuario.Rol), [Textos.CitaNegativa()], ResultadoAuditoria.FugaBloqueada)
439	            : null;
440	
441	    private static SalidaVerificada? RechazoPorConfiguracion(
442	        string respuesta,
443	        IReadOnlyCollection<string> textosFuente,
444	        MaterialConfidencial? confidencial) =>
445	        confidencial is not null && DetectorFugaConfiguracion.HayFuga(respuesta, confidencial, textosFuente)
446	            ? new SalidaVerificada(Textos.SinInformacion, [], ResultadoAuditoria.FugaBloqueada)
447	            : null;
448	
449	    private static SalidaVerificada? RechazoPorValorMonetario(string respuesta, IReadOnlyCollection<string> textosFuente) =>
450	        DetectorValorMonetario.HayValorNoRespaldado(respuesta, textosFuente)
451	            ? new SalidaVerificada(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion)
452	            : null;
453	
454	    private SalidaVerificada? RechazoPorNumero(string respuesta, IReadOnlyCollection<string> textosFuente) =>
455	        TodosLosNumerosSonVerificables(respuesta, textosFuente)
456	            ? null
457	            : new SalidaVerificada(Textos.NoVerificable, [], ResultadoAuditoria.NumeroNoVerificado);
458	
459	    public IReadOnlyList<Cita> DescartarCitasInexistentes(IReadOnlyList<Cita> citas, IBaseConocimiento baseConocimiento) =>
460	        citas.Where(cita => !_documentosDerogados.Contains(cita.Documento) && baseConocimiento.ObtenerSeccion(cita) is not null).ToList();
461	
462	    public bool ContienePersonaNoAutorizada(string respuesta, IReadOnlyCollection<string> idsPersonasAutorizadas, DirectorioAcademico directorio)
463	    {
464	        var normalizada = _normalizar(respuesta);
465	        return DetectorTerceros.PersonasMencionadas(normalizada, directorio).Any(id => !idsPersonasAutorizadas.Contains(id))
466	            || DetectorTerceros.MencionaIdFueraDe(normalizada, idsPersonasAutorizadas, directorio);
467	    }
468	
469	    public bool TodosLosNumerosSonVerificables(string respuesta, IReadOnlyCollection<string> textosFuente)
470	    {
471	        var numerosDeFuentes = textosFuente
472	            .SelectMany(texto => _numero.Matches(texto).Select(coincidencia => coincidencia.Value))
473	            .ToHashSet();
474	        return NumerosAVerificar(respuesta).All(numerosDeFuentes.Contains);
475	    }
476	
477	    private IEnumerable<string> NumerosAVerificar(string respuesta) =>
478	        _notaOPorcentaje.Matches(ReferenciasASeccion.Quitar(TokenizadorTexto.Plegado(respuesta)))
479	            .Select(coincidencia => coincidencia.Groups["numero"].Value);
480	
481	    [GeneratedRegex(@"(?<![0-9.])[0-9]+(\.[0-9]+)?", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
482	    private static partial Regex Numero();
483	
484	    [GeneratedRegex(@"(?<![0-9.])(?<numero>[0-9]\.[0-9]{1,2})(?![0-9])|(?<![0-9.])(?<numero>[0-9]+(\.[0-9]+)?)(?=\s*%)", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
485	    private static partial Regex NotaOPorcentaje();
486	}

