  1	using TutorFlow.Core.Autorizacion;
  2	using TutorFlow.Core.Conocimiento;
  3	
  4	namespace TutorFlow.Core.Asistente;
  5	
  6	internal sealed class CierreDeRespuesta
  7	{
  8	    private const int MaximoCitasDeReglasAplicadas = 3;
  9	
 10	    private readonly IBaseConocimiento _baseConocimiento;
 11	    private readonly PoliticaAcceso _politicaAcceso;
 12	    private readonly VerificadorSalida _verificadorSalida;
 13	    private readonly ConfiguracionAsistente _configuracion;
 14	    private readonly EmisorDeResultados _emisor;
 15	    private readonly CitasDeRespuesta _citasDeRespuesta;
 16	    private readonly OrdenDeReglasPorRelevancia _ordenDeReglas;
 17	    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
 18	    private readonly DefinitivaPorAsignatura _definitivaPorAsignatura;
 19	
 20	    public CierreDeRespuesta(
 21	        IBaseConocimiento baseConocimiento,
 22	        PoliticaAcceso politicaAcceso,
 23	        VerificadorSalida verificadorSalida,
 24	        ConfiguracionAsistente configuracion,
 25	        EmisorDeResultados emisor)
 26	    {
 27	        _baseConocimiento = baseConocimiento;
 28	        _politicaAcceso = politicaAcceso;
 29	        _verificadorSalida = verificadorSalida;
 30	        _configuracion = configuracion;
 31	        _emisor = emisor;
 32	        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
 33	        _ordenDeReglas = new OrdenDeReglasPorRelevancia(baseConocimiento);
 34	        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
 35	        _definitivaPorAsignatura = new DefinitivaPorAsignatura(configuracion.Catalogo);
 36	    }
 37	
 38	    public ResultadoPregunta Completar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
 39	    {
 40	        if (texto.Trim() == Textos.SinInformacion)
 41	        {
 42	            return _emisor.SinInformacion(sesion);
 43	        }
 44	
 45	        foreach (var seccion in entrada.Secciones)
 46	        {
 47	            sesion.Registro.AgregarFuente($"{seccion.Titulo}. {seccion.Texto}");
 48	        }
 49	
 50	        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
 51	        var verificada = Verificar(sesion, texto, entrada, autorizados);
 52	        return verificada.Resultado == ResultadoAuditoria.Respondida
 53	            ? ResponderSiLasAfirmacionesSeRespaldan(sesion, verificada, entrada, autorizados)
 54	            : _emisor.Responder(sesion, verificada.Respuesta, verificada.Citas, verificada.Resultado);
 55	    }
 56	
 57	    private SalidaVerificada Verificar(SesionPregunta sesion, string texto, EntradaConversacion entrada, IReadOnlyCollection<string> autorizados)
 58	    {
 59	        var candidatas = _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas);
 60	        return _verificadorSalida.Verificar(
 61	            sesion.Entrada.Usuario,
 62	            texto,
 63	            candidatas,
 64	            autorizados,
 65	            sesion.Registro.Fuentes,
 66	            _baseConocimiento,
 67	            sesion.Directorio,
 68	            Confidencial(sesion, entrada));
 69	    }
 70	
 71	    private ResultadoPregunta ResponderSiLasAfirmacionesSeRespaldan(
 72	        SesionPregunta sesion,
 73	        SalidaVerificada verificada,
 74	        EntradaConversacion entrada,
 75	        IReadOnlyCollection<string> autorizados) =>
 76	        AfirmacionesSonVerificables(sesion, verificada.Respuesta, autorizados)
 77	            ? ResponderVerificada(sesion, verificada, entrada)
 78	            : _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado);
 79	
 80	    private bool AfirmacionesSonVerificables(SesionPregunta sesion, string respuesta, IReadOnlyCollection<string> autorizados)
 81	    {
 82	        var usuario = sesion.Entrada.Usuario;
 83	        var resumenes = sesion.Registro.Resumenes;
 84	        return _afirmacionesDePerdida.SonVerificables(respuesta, usuario.Rol, autorizados, sesion.Directorio, resumenes)
 85	            && _definitivaPorAsignatura.SonVerificables(respuesta, usuario, autorizados, sesion.Directorio, resumenes);
 86	    }
 87	
 88	    private ResultadoPregunta ResponderVerificada(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
 89	    {
 90	        var citasDeTextoFijo = Textos.CitasDeTextoFijo(verificada.Respuesta);
 91	        if (citasDeTextoFijo is not null)
 92	        {
 93	            return _emisor.Responder(sesion, verificada.Respuesta, citasDeTextoFijo, verificada.Resultado);
 94	        }
 95	
 96	        var citasDeDocumento = CitasDeDocumento(sesion, verificada, entrada);
 97	        if (citasDeDocumento.Count == 0 && !sesion.Registro.UsoDatos)
 98	        {
 99	            return _emisor.SinInformacion(sesion);
100	        }
101	
102	        IReadOnlyList<Cita> citas = [.. citasDeDocumento.Concat(sesion.Registro.Citas).Distinct()];
103	        return ResponderSinReferenciasHuerfanas(sesion, verificada, citas);
104	    }
105	
106	    private ResultadoPregunta ResponderSinReferenciasHuerfanas(SesionPregunta sesion, SalidaVerificada verificada, IReadOnlyList<Cita> citas)
107	    {
108	        var limpia = ReferenciasEscritas.Limpiar(verificada.Respuesta, citas);
109	        return ReferenciasEscritas.TienePalabras(limpia)
110	            ? _emisor.Responder(sesion, limpia, citas, verificada.Resultado)
111	            : _emisor.Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion);
112	    }
113	
114	    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
115	    {
116	        var reglasAplicadas = _ordenDeReglas.Ordenar(sesion.Registro.Reglas, sesion.Entrada.Pregunta).Take(MaximoCitasDeReglasAplicadas);
117	        IReadOnlyList<Cita> escritasYReglas = [.. verificada.Citas.Concat(reglasAplicadas).Distinct()];
118	        return escritasYReglas.Count > 0
119	            ? escritasYReglas
120	            : _citasDeRespuesta.Respaldo(verificada.Respuesta, entrada.Secciones);
121	    }
122	
123	    private MaterialConfidencial Confidencial(SesionPregunta sesion, EntradaConversacion entrada) =>
124	        new(
125	            _configuracion.MarcadorCanario,
126	            [ConstructorPrompts.Instrucciones(entrada.PromptSistema), .. DescripcionesDeHerramientas(sesion.Entrada.Usuario.Rol)],
127	            HerramientasAsistente.NombresInternos);
128	
129	    private static IEnumerable<string> DescripcionesDeHerramientas(Rol rol) =>
130	        HerramientasAsistente.Definir(rol)
131	            .SelectMany(herramienta => herramienta.Parametros.Select(parametro => parametro.Descripcion).Prepend(herramienta.Descripcion));
132	}
133	using System.Text.RegularExpressions;
134	using TutorFlow.Core.Autorizacion;
135	using TutorFlow.Core.Conocimiento;
