243	public static class ReglasAplicadas
244	{
245	    public const string DocumentoReglamento = "reglamento_academico_2025.md";
246	    public const string DocumentoEvaluacion = "evaluacion_y_calificaciones.md";
247	    public const string DocumentoBienestar = "bienestar_y_becas.md";
248	
249	    private static readonly IReadOnlyList<ReglaCondicionada> OrdenFijo =
250	    [
251	        new(new Cita(DocumentoEvaluacion, Textos.SeccionDefinitiva), lectura => lectura.Notas),
252	        new(new Cita(DocumentoEvaluacion, Textos.SeccionPromedio), lectura => lectura.Notas),
