254	        new(new Cita(DocumentoBienestar, Textos.SeccionBecaPorRendimiento), lectura => lectura.Notas),
255	        new(new Cita(DocumentoReglamento, Textos.SeccionNotaMinima), lectura => lectura.Hay(EstadoAsignatura.Perdida)),
256	        new(new Cita(DocumentoReglamento, Textos.SeccionHabilitacion), lectura => lectura.Hay(EstadoAsignatura.Perdida)),
257	        new(new Cita(DocumentoReglamento, Textos.SeccionNoHabilitables), lectura => lectura.Hay(EstadoAsignatura.PerdidaPorInasistencia)),
258	        new(new Cita(DocumentoReglamento, Textos.SeccionPerdidaPorInasistencia), lectura => lectura.Hay(EstadoAsignatura.PerdidaPorInasistencia)),
259	        new(new Cita(DocumentoReglamento, Textos.SeccionPruebaAcademica), lectura => lectura.PruebaAcademica),
260	        new(new Cita(DocumentoReglamento, Textos.SeccionAsistenciaSinRegistro), lectura => lectura.AsistenciaSinRegistro),
261	        new(new Cita(DocumentoEvaluacion, Textos.SeccionDefinitiva), lectura => lectura.Hay(EstadoAsignatura.SinDefinitiva))
262	    ];
263	
264	    public static IReadOnlyList<int> DeNotas(IReadOnlyList<ResumenEstudiante> resumenes) =>
265	        Entradas(new LecturaDeReglas(true, false, resumenes));
266	
267	    public static IReadOnlyList<int> DeAsistencia(IReadOnlyList<ResumenEstudiante> resumenes) =>
268	        Entradas(new LecturaDeReglas(false, true, resumenes));
269	
270	    public static IReadOnlyList<int> DeNotasYAsistencia(IReadOnlyList<ResumenEstudiante> resumenes) =>
271	        Entradas(new LecturaDeReglas(true, true, resumenes));
272	
273	    public static IReadOnlyList<int> DePrograma(IReadOnlyList<ResumenEstudiante> resumenes) =>
274	        Entradas(new LecturaDeReglas(false, false, resumenes));
275	
276	    public static IReadOnlyList<Cita> Citas(IEnumerable<int> entradas) =>
277	        [.. entradas.Distinct().Order().Select(entrada => OrdenFijo[entrada].Cita).Distinct()];
278	
279	    private static List<int> Entradas(LecturaDeReglas lectura) =>
280	        [.. Enumerable.Range(0, OrdenFijo.Count).Where(entrada => OrdenFijo[entrada].Aplica(lectura))];
281	
282	    private sealed record ReglaCondicionada(Cita Cita, Func<LecturaDeReglas, bool> Aplica);
283	
284	    private sealed record LecturaDeReglas(bool Notas, bool Asistencia, IReadOnlyList<ResumenEstudiante> Resumenes)
285	    {
286	        private IEnumerable<ResultadoAsignatura> Resultados => Resumenes.SelectMany(resumen => resumen.Asignaturas);
287	
288	        public bool PruebaAcademica => Resumenes.Any(resumen => resumen.PruebaAcademica);
289	
290	        public bool AsistenciaSinRegistro => Resultados.Any(r => r.EstadoAsistencia == EstadoAsistencia.SinRegistro);
291	
292	        public bool Hay(EstadoAsignatura estado) => Resultados.Any(r => r.Estado == estado);
293	    }
294	}
