 38	    public ResultadoPregunta Completar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
 39	    {
 40	        if (texto.Trim() == Textos.SinInformacion)
 41	        {
 42	            return _emisor.SinInformacion(sesion);
 43	        }
 44	
 45	        foreach (var seccion in entrada.Secciones)
 46	        {
 47	            sesion.Registro.AgregarFuente($"{seccion.Titulo}. {seccion.Texto}");
 48	        }
 49	
 50	        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
 51	        var verificada = Verificar(sesion, texto, entrada, autorizados);
 52	        return verificada.Resultado == ResultadoAuditoria.Respondida
 53	            ? ResponderSiLasAfirmacionesSeRespaldan(sesion, verificada, entrada, autorizados)
 54	            : _emisor.Responder(sesion, verificada.Respuesta, verificada.Citas, verificada.Resultado);
 55	    }
