 57	    private SalidaVerificada Verificar(SesionPregunta sesion, string texto, EntradaConversacion entrada, IReadOnlyCollection<string> autorizados)
 58	    {
 59	        var candidatas = _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas);
 60	        return _verificadorSalida.Verificar(
 61	            sesion.Entrada.Usuario,
 62	            texto,
 63	            candidatas,
 64	            autorizados,
 65	            sesion.Registro.Fuentes,
 66	            _baseConocimiento,
 67	            sesion.Directorio,
 68	            Confidencial(sesion, entrada));
 69	    }
 70	
 71	    private ResultadoPregunta ResponderSiLasAfirmacionesSeRespaldan(
 72	        SesionPregunta sesion,
 73	        SalidaVerificada verificada,
 74	        EntradaConversacion entrada,
 75	        IReadOnlyCollection<string> autorizados) =>
 76	        AfirmacionesSonVerificables(sesion, verificada.Respuesta, autorizados)
 77	            ? ResponderVerificada(sesion, verificada, entrada)
 78	            : _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado);
 79	
 80	    private bool AfirmacionesSonVerificables(SesionPregunta sesion, string respuesta, IReadOnlyCollection<string> autorizados)
 81	    {
 82	        var usuario = sesion.Entrada.Usuario;
 83	        var resumenes = sesion.Registro.Resumenes;
 84	        return _afirmacionesDePerdida.SonVerificables(respuesta, usuario.Rol, autorizados, sesion.Directorio, resumenes)
 85	            && _definitivaPorAsignatura.SonVerificables(respuesta, usuario, autorizados, sesion.Directorio, resumenes);
 86	    }
