 88	    private ResultadoPregunta ResponderVerificada(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
 89	    {
 90	        var citasDeTextoFijo = Textos.CitasDeTextoFijo(verificada.Respuesta);
 91	        if (citasDeTextoFijo is not null)
 92	        {
 93	            return _emisor.Responder(sesion, verificada.Respuesta, citasDeTextoFijo, verificada.Resultado);
 94	        }
 95	
 96	        var citasDeDocumento = CitasDeDocumento(sesion, verificada, entrada);
 97	        if (citasDeDocumento.Count == 0 && !sesion.Registro.UsoDatos)
 98	        {
 99	            return _emisor.SinInformacion(sesion);
100	        }
101	
102	        IReadOnlyList<Cita> citas = [.. citasDeDocumento.Concat(sesion.Registro.Citas).Distinct()];
103	        return ResponderSinReferenciasHuerfanas(sesion, verificada, citas);
104	    }
105	
106	    private ResultadoPregunta ResponderSinReferenciasHuerfanas(SesionPregunta sesion, SalidaVerificada verificada, IReadOnlyList<Cita> citas)
107	    {
108	        var limpia = ReferenciasEscritas.Limpiar(verificada.Respuesta, citas);
