111	            : _emisor.Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion);
112	    }
113	
114	    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
115	    {
116	        var reglasAplicadas = _ordenDeReglas.Ordenar(sesion.Registro.Reglas, sesion.Entrada.Pregunta).Take(MaximoCitasDeReglasAplicadas);
117	        IReadOnlyList<Cita> escritasYReglas = [.. verificada.Citas.Concat(reglasAplicadas).Distinct()];
118	        return escritasYReglas.Count > 0
119	            ? escritasYReglas
120	            : _citasDeRespuesta.Respaldo(verificada.Respuesta, entrada.Secciones);
121	    }
