139	public static partial class ReferenciasEscritas
140	{
141	    private const char Marca = '';
142	    private const int PalabrasMinimasPorOracion = 3;
143	    private const string DocumentoDerogado = "reglamento_academico_2023.md";
144	    private const string FinDePalabra = @"(?![\p{L}\p{N}_-])";
145	    private const string Parada = "(?:según|segun|ver|consulta|en|de|del|con|a|al|el|la|los|las)";
146	    private const string PalabraIzquierda = @"(?:(?!" + Parada + FinDePalabra + @")[\p{L}_-]+ +)";
147	    private const string Numero = @"\d+(?:\.\d+)*";
148	    private const string Documento =
149	        @"(?<doc>(?<![\p{L}\p{N}_-])(?:" + PalabraIzquierda + @"{1,3}\d+\.md|[\p{L}\p{N}_-]+\.md)" + FinDePalabra + ")";
150	    private const string Seccion =
151	        @"(?<sec>(?<![\p{L}\p{N}])(?:secci[oó]n(?:es)?|art[ií]culos?|art\.?|§)\s*" + Numero + @"(?:\s*(?:,|y|e)\s*" + Numero + ")*)";
152	    private const string Conector =
153	        @"(?:(?<![\p{L}\p{N}_-])(?:(?:según|segun|de\s+acuerdo\s+con|conforme\s+al?|ver|consulta|se\s+respaldan?\s+en|en|de|del)"
154	        + @"(?:\s+(?:el|la|los|las))?|(?:el|la|los|las))\s+)?";
155	    private const string ConectorHaciaDocumento = @"\s+(?:de\s+la|del|de|en\s+el|en)\s+";
156	    private const string PatronReferencia =
157	        Conector + "(?:" + Seccion + ConectorHaciaDocumento + Documento
158	        + "|" + Documento + @"\s*[·,:-]\s*" + Seccion
159	        + "|" + Documento + ")";
160	
161	    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos);
162	
163	    private static readonly (Regex Patron, string Reemplazo)[] ReglasDeSignos =
164	    [
165	        (new Regex(@"[\(\[][\s·,;:]*[\)\]]", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
166	        (new Regex(@" {2,}", RegexOptions.CultureInvariant, LimiteRegex), " "),
167	        (new Regex(@" +(?=[.,;:!?)])", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
168	        (new Regex(@"(?<!\.)\.\.(?!\.)", RegexOptions.CultureInvariant, LimiteRegex), "."),
169	        (new Regex(@"[,;:]\.", RegexOptions.CultureInvariant, LimiteRegex), "."),
170	        (new Regex(@",,", RegexOptions.CultureInvariant, LimiteRegex), ",")
171	    ];
172	
173	    public static string Limpiar(string respuesta, IReadOnlyList<Cita> citas)
174	    {
175	        var marcada = Referencia().Replace(respuesta, coincidencia => EsValida(coincidencia, citas) ? coincidencia.Value : Marca.ToString());
176	        return marcada.Contains(Marca, StringComparison.Ordinal) ? Depurar(marcada) : respuesta;
177	    }
178	
179	    public static bool TienePalabras(string texto) => PalabraDeLetras().IsMatch(texto);
180	
181	    private static string Depurar(string marcada) =>
182	        string.Concat(CorteDeOracion().Split(marcada).Select(DepurarOracion)).Trim();
183	
184	    private static string DepurarOracion(string oracion) =>
185	        oracion.Contains(Marca, StringComparison.Ordinal)
186	            ? DepurarOracionConReferenciaEliminada(oracion.Replace(Marca.ToString(), string.Empty, StringComparison.Ordinal))
187	            : oracion;
188	
189	    private static string DepurarOracionConReferenciaEliminada(string oracion) =>
190	        Palabras(oracion) < PalabrasMinimasPorOracion
191	            ? string.Empty
192	            : Capitalizar(ReglasDeSignos.Aggregate(oracion, (texto, regla) => regla.Patron.Replace(texto, regla.Reemplazo)));
193	
194	    private static int Palabras(string oracion) => PalabraOCifra().Count(oracion);
195	
196	    private static string Capitalizar(string oracion)
197	    {
198	        var inicio = oracion.Length - oracion.TrimStart().Length;
199	        return inicio < oracion.Length && char.IsLower(oracion[inicio])
200	            ? string.Concat(oracion.AsSpan(0, inicio), char.ToUpperInvariant(oracion[inicio]).ToString(), oracion.AsSpan(inicio + 1))
201	            : oracion;
202	    }
203	
204	    private static bool EsValida(Match coincidencia, IReadOnlyList<Cita> citas)
205	    {
206	        var documento = PlegadoCompatibilidad.Aplicar(coincidencia.Groups["doc"].Value);
207	        var seccion = coincidencia.Groups["sec"];
208	        return seccion.Success
209	            ? NumerosDe(seccion.Value).All(numero => citas.Any(cita => EsCitaDe(cita, documento, numero)))
210	            : string.Equals(documento, DocumentoDerogado, StringComparison.OrdinalIgnoreCase)
211	                || citas.Any(cita => MismoDocumento(cita, documento));
212	    }
213	
214	    private static IEnumerable<string> NumerosDe(string seccion) =>
215	        NumeroDeSeccion().Matches(seccion).Select(numero => numero.Value);
216	
217	    private static bool EsCitaDe(Cita cita, string documento, string numero) =>
218	        MismoDocumento(cita, documento) && NumeroDeSeccion().Matches(cita.Seccion).LastOrDefault()?.Value == numero;
219	
220	    private static bool MismoDocumento(Cita cita, string documento) =>
221	        string.Equals(PlegadoCompatibilidad.Aplicar(cita.Documento), documento, StringComparison.OrdinalIgnoreCase);
222	
223	    [GeneratedRegex(PatronReferencia, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
224	    private static partial Regex Referencia();
225	
226	    [GeneratedRegex(@"\d+(?:\.\d+)*", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
227	    private static partial Regex NumeroDeSeccion();
228	
229	    [GeneratedRegex(@"\p{L}{2,}", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
230	    private static partial Regex PalabraDeLetras();
231	
232	    [GeneratedRegex(@"[\p{L}\p{N}]+", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
233	    private static partial Regex PalabraOCifra();
234	
235	    [GeneratedRegex(@"(?<=\n)|(?<=[.!?;])(?=\s|$)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
236	    private static partial Regex CorteDeOracion();
237	}
