 35	        {
 36	            ModelId = _modelo,
 37	            MaxOutputTokens = solicitud.MaximoTokensSalida,
 38	            Tools = [.. solicitud.Herramientas.Select(Declarar)]
 39	        };
 40	        try
 41	        {
 42	            var respuesta = await _cliente.GetResponseAsync(Mensajes(solicitud), opciones, cancellationToken);
 43	            return Traducir(respuesta);
 44	        }
 45	        catch (ClientResultException)
 46	        {
 47	            throw new DependenciaNoDisponibleException("El proveedor del LLM respondió con un error.");
 48	        }
 49	    }
