 57	    private static List<ChatMessage> Mensajes(SolicitudLlm solicitud)
 58	    {
 59	        var mensajes = new List<ChatMessage> { new(ChatRole.System, solicitud.PromptSistema) };
 60	        mensajes.AddRange(solicitud.Mensajes.Select(Mensaje));
 61	        return mensajes;
 62	    }
 63	
 64	    private static ChatMessage Mensaje(MensajeLlm mensaje) => mensaje.Rol switch
 65	    {
 66	        RolMensaje.Herramienta => new ChatMessage(ChatRole.Tool, [new FunctionResultContent(mensaje.IdLlamada ?? string.Empty, mensaje.Contenido)]),
 67	        RolMensaje.Asistente => MensajeDeAsistente(mensaje),
 68	        _ => new ChatMessage(ChatRole.User, mensaje.Contenido)
 69	    };
 70	
 71	    private static ChatMessage MensajeDeAsistente(MensajeLlm mensaje)
 72	    {
 73	        var contenidos = new List<AIContent>();
 74	        if (!string.IsNullOrEmpty(mensaje.Contenido))
 75	        {
 76	            contenidos.Add(new TextContent(mensaje.Contenido));
 77	        }
 78	
 79	        contenidos.AddRange(mensaje.Llamadas.Select(llamada =>
 80	            new FunctionCallContent(llamada.Id, llamada.Nombre, ArgumentosDe(llamada.ArgumentosJson))));
 81	        return new ChatMessage(ChatRole.Assistant, contenidos);
 82	    }
 83	
 84	    private static Dictionary<string, object?> ArgumentosDe(string argumentosJson)
 85	    {
 86	        using var documento = JsonDocument.Parse(argumentosJson);
 87	        return documento.RootElement.ValueKind == JsonValueKind.Object
 88	            ? documento.RootElement.EnumerateObject().ToDictionary(p => p.Name, p => (object?)p.Value.Clone())
 89	            : [];
 90	    }
 91	
 92	    private static AIFunctionDeclaration Declarar(HerramientaLlm herramienta)
 93	    {
 94	        var propiedades = herramienta.Parametros.ToDictionary(
 95	            parametro => parametro.Nombre,
 96	            parametro => new { type = "string", description = parametro.Descripcion });
 97	        var esquema = JsonSerializer.SerializeToElement(new
 98	        {
 99	            type = "object",
100	            properties = propiedades,
101	            required = herramienta.Parametros.Where(p => p.Requerido).Select(p => p.Nombre).ToArray()
102	        });
103	        return AIFunctionFactory.CreateDeclaration(herramienta.Nombre, herramienta.Descripcion, esquema);
104	    }
105	
106	    private static RespuestaLlm Traducir(ChatResponse respuesta)
107	    {
108	        var rechazada = EsRechazo(respuesta);
109	        var texto = rechazada ? null : respuesta.Text;
110	        return new RespuestaLlm(
111	            string.IsNullOrEmpty(texto) ? null : texto,
112	            LlamadasDe(respuesta),
113	            UsoDe(respuesta.Usage),
114	            rechazada);
115	    }
116	
117	    private static bool EsRechazo(ChatResponse respuesta) =>
118	        respuesta.FinishReason == ChatFinishReason.ContentFilter
119	        || (respuesta.RawRepresentation is OpenAI.Chat.ChatCompletion completado && !string.IsNullOrEmpty(completado.Refusal));
120	
121	    private static List<LlamadaHerramienta> LlamadasDe(ChatResponse respuesta) =>
122	        [.. respuesta.Messages
123	            .SelectMany(mensaje => mensaje.Contents)
124	            .OfType<FunctionCallContent>()
125	            .Select(llamada => new LlamadaHerramienta(llamada.CallId, llamada.Name, JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>())))];
126	
127	    private static UsoTokens UsoDe(UsageDetails? uso) =>
128	        new((int)(uso?.InputTokenCount ?? 0), (int)(uso?.OutputTokenCount ?? 0));
129	}

