159	    private async Task<ResultadoHerramienta> ConsultarPrograma(SolicitudHerramienta solicitud)
160	    {
161	        var programas = _politicaAcceso.ProgramasAutorizados(solicitud.Contexto.Usuario, solicitud.Contexto.Directorio);
162	        if (programas.Count == 0)
163	        {
164	            return ResultadoHerramienta.Texto(Textos.SinProgramasAsignados);
165	        }
166	
167	        var bloques = new List<string>();
168	        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
169	        {
170	            bloques.Add(await DescribirProgramaAsync(solicitud, programa));
171	        }
172	
173	        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
174	    }
