384	internal sealed class AfirmacionesDePerdida
385	{
386	    private static readonly HashSet<string> Inasistencias = new(StringComparer.Ordinal)
387	    {
388	        "inasistencia", "inasistencias"
389	    };
390	
391	    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;
392	
393	    public AfirmacionesDePerdida(IReadOnlyList<AsignaturaCatalogo> catalogo)
394	    {
395	        _catalogo = catalogo;
396	    }
397	
398	    public bool SonVerificables(
399	        string respuesta,
400	        Rol rol,
401	        IReadOnlyCollection<string> idsAutorizados,
402	        DirectorioAcademico directorio,
403	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos) =>
404	        TramosDePersonas.DeRespuesta(respuesta, rol, idsAutorizados, directorio)
405	            .SelectMany(oracion => oracion.Tramos)
406	            .All(tramo => TramoEsVerificable(tramo, CatalogoAsignaturas.Vigente(_catalogo, directorio), resumenesLeidos));
407	
408	    private static bool TramoEsVerificable(TramoDePersona tramo, IReadOnlyList<AsignaturaCatalogo> catalogo, IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
409	    {
410	        var exigencias = Exigencias(tramo.Tokens, catalogo);
411	        return exigencias.Count == 0
412	            || (resumenesLeidos.TryGetValue(tramo.PersonaId, out var resumen) && exigencias.All(exigencia => exigencia.Cumple(resumen)));
413	    }
414	
415	    private static List<ExigenciaDePerdida> Exigencias(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<AsignaturaCatalogo> catalogo)
416	    {
417	        var formas = FormasDePerdida.En([.. tokens.Select(token => token.Valor)]);
418	        if (formas.Count == 0)
419	        {
420	            return [];
421	        }
422	
423	        var nombradas = PrimerasApariciones(tokens, catalogo);
424	        var asociadas = nombradas.Select(nombrada => (Nombrada: nombrada, Forma: FormaMasCercana(formas, nombrada))).ToList();
425	        var porAsignatura = asociadas
426	            .Where(asociada => !asociada.Forma.Negada)
427	            .Select(asociada => new ExigenciaDePerdida(asociada.Nombrada.Clave, PorInasistencia(tokens, nombradas, asociada.Nombrada)));
428	        var sinAsignatura = formas
429	            .Where(forma => forma.Nominal && !forma.Negada && asociadas.All(asociada => asociada.Forma != forma))
430	            .Select(forma => new ExigenciaDePerdida(null, forma.PorInasistencia));
431	        return [.. porAsignatura.Concat(sinAsignatura)];
432	    }
433	
434	    private static List<AparicionDeAsignatura> PrimerasApariciones(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<AsignaturaCatalogo> catalogo) =>
435	        [.. CatalogoAsignaturas.Apariciones(tokens, catalogo)
436	            .GroupBy(aparicion => aparicion.Clave)
437	            .Select(grupo => grupo.MinBy(aparicion => aparicion.Inicio)!)
438	            .OrderBy(aparicion => aparicion.Inicio)];
439	
440	    private static FormaDePerdida FormaMasCercana(IReadOnlyList<FormaDePerdida> formas, AparicionDeAsignatura asignatura) =>
441	        formas.MinBy(forma => (Distancia(forma, asignatura), forma.Fin >= asignatura.Inicio))!;
442	
443	    private static int Distancia(FormaDePerdida forma, AparicionDeAsignatura asignatura) =>
444	        forma.Fin < asignatura.Inicio ? asignatura.Inicio - forma.Fin : Math.Max(0, forma.Inicio - asignatura.Fin);
445	
446	    private static bool PorInasistencia(
447	        IReadOnlyList<TokenTexto> tokens,
448	        List<AparicionDeAsignatura> nombradas,
449	        AparicionDeAsignatura asignatura)
450	    {
451	        var inasistencias = Enumerable.Range(0, tokens.Count).Where(indice => Inasistencias.Contains(tokens[indice].Valor)).ToList();
452	        var siguiente = nombradas.Where(nombrada => nombrada.Inicio > asignatura.Inicio).Select(nombrada => nombrada.Inicio).DefaultIfEmpty(int.MaxValue).Min();
453	        return inasistencias.Any(indice => indice < nombradas[0].Inicio || (indice >= asignatura.Inicio && indice < siguiente));
454	    }
455	
456	    private sealed record ExigenciaDePerdida(string? Clave, bool PorInasistencia)
457	    {
458	        public bool Cumple(ResumenEstudiante resumen) =>
459	            resumen.Asignaturas.Any(resultado => (Clave is null || AmbitoPersonal.Clave(resultado.Asignatura.Codigo) == Clave) && Satisface(resultado));
460	
461	        private bool Satisface(ResultadoAsignatura resultado) =>
462	            PorInasistencia
463	                ? resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia
464	                : resultado.Estado is EstadoAsignatura.Perdida or EstadoAsignatura.PerdidaPorInasistencia;
465	    }
466	}
