 44	    public bool SonVerificables(
 45	        string respuesta,
 46	        Usuario usuario,
 47	        IReadOnlyCollection<string> idsAutorizados,
 48	        DirectorioAcademico directorio,
 49	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos) =>
 50	        TramosDePersonas.DeRespuesta(respuesta, usuario.Rol, idsAutorizados, directorio)
 51	            .SelectMany(oracion => Atribuciones(oracion, usuario, CatalogoAsignaturas.Vigente(_catalogo, directorio)))
 52	            .All(atribucion => Coincide(atribucion, resumenesLeidos));
 53	
 54	    private static IEnumerable<AtribucionDeDefinitiva> Atribuciones(OracionAnalizada oracion, Usuario usuario, IReadOnlyList<AsignaturaCatalogo> catalogo)
 55	    {
 56	        var tokens = TokenizadorTexto.TokenizarConCifras(oracion.Texto);
 57	        var apariciones = CatalogoAsignaturas.Apariciones(tokens, catalogo);
 58	        return Enumerable.Range(0, tokens.Count)
 59	            .Where(indice => tokens[indice].Valor == Definitiva && !EstaNegada(tokens, indice))
 60	            .Select(indice => (Definitiva: indice, Cifra: CifraAsociada(tokens, indice)))
 61	            .Where(par => par.Cifra is { } cifra && !EsUmbral(tokens, par.Definitiva, cifra))
 62	            .Select(par => par.Cifra!.Value)
 63	            .SelectMany(cifra => Atribuir(oracion, usuario, tokens, apariciones, cifra));
 64	    }
 65	
 66	    private static IEnumerable<AtribucionDeDefinitiva> Atribuir(
 67	        OracionAnalizada oracion,
 68	        Usuario usuario,
 69	        IReadOnlyList<TokenTexto> tokens,
 70	        IReadOnlyList<AparicionDeAsignatura> apariciones,
 71	        int cifra)
 72	    {
 73	        var asignatura = apariciones.MinBy(aparicion => (Distancia(aparicion, cifra), aparicion.Inicio > cifra));
 74	        return asignatura is null
 75	            ? []
 76	            : PersonasDe(oracion, usuario, tokens[asignatura.Inicio].Inicio)
 77	                .Select(persona => new AtribucionDeDefinitiva(persona, asignatura.Clave, tokens[cifra].Valor));
 78	    }
 79	
 80	    private static int Distancia(AparicionDeAsignatura asignatura, int cifra) =>
 81	        asignatura.Fin < cifra ? cifra - asignatura.Fin : asignatura.Inicio - cifra;
 82	
 83	    private static IEnumerable<string> PersonasDe(OracionAnalizada oracion, Usuario usuario, int posicion) =>
 84	        usuario.Rol == Rol.Coordinador
 85	            ? oracion.Tramos.Where(tramo => tramo.Tokens.Any(token => token.Inicio == posicion)).Select(tramo => tramo.PersonaId)
 86	            : [usuario.Id];
 87	
 88	    private static bool EsUmbral(IReadOnlyList<TokenTexto> tokens, int definitiva, int cifra) =>
 89	        PrecedidaDeComparador(tokens, cifra) || HayVerboDeRequisito(tokens, definitiva, cifra);
 90	
 91	    private static bool PrecedidaDeComparador(IReadOnlyList<TokenTexto> tokens, int cifra) =>
 92	        TerminaComparador(tokens, cifra - 1) || (cifra > 0 && Enlaces.Contains(tokens[cifra - 1].Valor) && TerminaComparador(tokens, cifra - 2));
 93	
 94	    private static bool TerminaComparador(IReadOnlyList<TokenTexto> tokens, int indice) =>
 95	        indice >= 0
 96	        && (Comparadores.Contains(tokens[indice].Valor)
 97	            || (indice > 0 && ComparadoresDeDosPalabras.Contains((tokens[indice - 1].Valor, tokens[indice].Valor))));
 98	
 99	    private static bool HayVerboDeRequisito(IReadOnlyList<TokenTexto> tokens, int definitiva, int cifra) =>
100	        (cifra > 0 && Requisitos.Contains(tokens[cifra - 1].Valor))
101	        || Enumerable.Range(Math.Max(0, definitiva - PalabrasDeRequisito), Math.Min(PalabrasDeRequisito, definitiva))
102	            .Any(anterior => Requisitos.Contains(tokens[anterior].Valor));
103	
104	    private static bool EstaNegada(IReadOnlyList<TokenTexto> tokens, int indice) =>
105	        Enumerable.Range(Math.Max(0, indice - PalabrasDeNegacion), Math.Min(PalabrasDeNegacion, indice))
106	            .Any(anterior => Negaciones.Contains(tokens[anterior].Valor));
107	
108	    private static int? CifraAsociada(IReadOnlyList<TokenTexto> tokens, int indice)
109	    {
110	        var despues = Enumerable.Range(indice + 1, Math.Min(PalabrasHastaLaCifra, tokens.Count - indice - 1));
111	        var antes = Enumerable.Range(Math.Max(0, indice - PalabrasHastaLaCifra), Math.Min(PalabrasHastaLaCifra, indice)).Reverse();
112	        return despues.Concat(antes).Where(posicion => EsCifraDeNota(tokens, posicion)).Select(posicion => (int?)posicion).FirstOrDefault();
113	    }
114	
115	    private static bool EsCifraDeNota(IReadOnlyList<TokenTexto> tokens, int posicion) =>
116	        CifraDeNota().IsMatch(tokens[posicion].Valor)
117	        && !(posicion > 0 && PalabrasDeReferencia.Contains(tokens[posicion - 1].Valor));
118	
119	    private static bool Coincide(AtribucionDeDefinitiva atribucion, IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
120	    {
121	        if (!resumenesLeidos.TryGetValue(atribucion.PersonaId, out var resumen))
122	        {
123	            return true;
124	        }
125	
126	        var resultado = resumen.Asignaturas.FirstOrDefault(r => AmbitoPersonal.Clave(r.Asignatura.Codigo) == atribucion.Clave);
127	        return resultado is null
128	            || resultado.Definitiva == decimal.Parse(atribucion.Cifra, CultureInfo.InvariantCulture);
129	    }
130	
131	    [GeneratedRegex(@"^\d\.\d{1,2}\z", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
132	    private static partial Regex CifraDeNota();
133	
134	    private sealed record AtribucionDeDefinitiva(string PersonaId, string Clave, string Cifra);
135	}
