     1	using TutorFlow.Core.Autorizacion;
     2	
     3	namespace TutorFlow.Core.Asistente;
     4	
     5	public sealed record MaterialConfidencial(
     6	    string Marcador,
     7	    IReadOnlyCollection<string> TextosConfidenciales,
     8	    IReadOnlyCollection<string> NombresDeHerramientas);
     9	
    10	public static class DetectorFugaConfiguracion
    11	{
    12	    public const int PalabrasMinimasDeFragmento = 8;
    13	
    14	    public static bool HayFuga(string respuesta, MaterialConfidencial material, IReadOnlyCollection<string> textosEntregados) =>
    15	        Contiene(respuesta, material.Marcador)
    16	        || material.NombresDeHerramientas.Any(nombre => Contiene(respuesta, nombre))
    17	        || ComparteFragmentoConfidencial(respuesta, material.TextosConfidenciales, textosEntregados);
    18	
    19	    private static bool Contiene(string texto, string valor) =>
    20	        texto.Contains(valor, StringComparison.OrdinalIgnoreCase);
    21	
    22	    private static bool ComparteFragmentoConfidencial(
    23	        string respuesta,
    24	        IReadOnlyCollection<string> textosConfidenciales,
    25	        IReadOnlyCollection<string> textosEntregados)
    26	    {
    27	        var permitidos = TextosFijos().Concat(textosEntregados).SelectMany(FragmentosDe).ToHashSet(StringComparer.Ordinal);
    28	        var confidenciales = textosConfidenciales.SelectMany(FragmentosDe).ToHashSet(StringComparer.Ordinal);
    29	        return FragmentosDe(respuesta).Any(fragmento => confidenciales.Contains(fragmento) && !permitidos.Contains(fragmento));
    30	    }
    31	
    32	    private static string[] TextosFijos() =>
    33	        [Textos.SinInformacion, Textos.NegativaEstudiante, Textos.NegativaCoordinador, Textos.NoVerificable];
    34	
    35	    private static HashSet<string> FragmentosDe(string texto)
    36	    {
    37	        string[] palabras = [.. TokenizadorTexto.Valores(texto)];
    38	        return Enumerable.Range(0, Math.Max(0, palabras.Length - PalabrasMinimasDeFragmento + 1))
    39	            .Select(inicio => string.Join(' ', palabras[inicio..(inicio + PalabrasMinimasDeFragmento)]))
    40	            .ToHashSet(StringComparer.Ordinal);
    41	    }
    42	}

