 1	using TutorFlow.Core.Asistente;
 2	using TutorFlow.Core.Autorizacion;
 3	using TutorFlow.Core.Conocimiento;
 4	
 5	namespace TutorFlow.Infrastructure.Conocimiento;
 6	
 7	public sealed class BaseConocimientoEnMemoria : IBaseConocimiento
 8	{
 9	    private const int LongitudMaximaDeRaiz = ConsultaDeRecuperacion.LongitudDeRaiz;
10	    private const int LongitudMinimaDeTermino = 3;
11	    private const double ParametroK1 = 1.5;
12	    private const double ParametroB = 0.75;
13	    private const double PesoDelTitulo = 4.0;
14	
15	    private readonly List<SeccionIndexada> _secciones;
16	    private readonly Dictionary<string, int> _frecuenciaDeDocumento;
17	    private readonly double _longitudPromedio;
18	
19	    public BaseConocimientoEnMemoria(IEnumerable<SeccionDocumento> secciones)
20	    {
21	        _secciones = secciones.Select(seccion => new SeccionIndexada(seccion, ExtraerRaices(seccion.Titulo + " " + seccion.Texto))).ToList();
22	        _frecuenciaDeDocumento = _secciones
23	            .SelectMany(indexada => indexada.Frecuencias.Keys)
24	            .GroupBy(raiz => raiz)
25	            .ToDictionary(grupo => grupo.Key, grupo => grupo.Count());
26	        _longitudPromedio = _secciones.Count == 0 ? 1 : _secciones.Average(indexada => (double)indexada.Longitud);
27	    }
28	
29	    public IReadOnlyList<SeccionDocumento> BuscarSecciones(string consulta, int maximo)
30	    {
31	        var terminos = ExpansionDeTerminos.Expandir(ExtraerRaices(consulta).Frecuencias.Keys);
32	        return _secciones
33	            .Select(indexada => (indexada.Seccion, Puntaje: Puntuar(indexada, terminos)))
34	            .Where(par => par.Puntaje > 0)
35	            .OrderByDescending(par => par.Puntaje)
36	            .Take(maximo)
37	            .Select(par => par.Seccion)
38	            .ToList();
39	    }
40	
41	    public SeccionDocumento? ObtenerSeccion(Cita cita) =>
42	        _secciones.Select(indexada => indexada.Seccion).FirstOrDefault(seccion => seccion.Documento == cita.Documento && seccion.Seccion == cita.Seccion);
43	
44	    private static Raices ExtraerRaices(string texto)
45	    {
46	        var frecuencias = NormalizadorTexto.Normalizar(texto)
47	            .Split(' ', StringSplitOptions.RemoveEmptyEntries)
48	            .Where(palabra => palabra.Length >= LongitudMinimaDeTermino && !PalabrasVacias.Contiene(palabra))
49	            .Select(palabra => palabra.Length > LongitudMaximaDeRaiz ? palabra[..LongitudMaximaDeRaiz] : palabra)
50	            .GroupBy(raiz => raiz)
