  const fuga = evs.find(e => e.tipo === 'seg10_diag')?.datos.fuga_config;
  const r = fin ? fin.datos.resultado : '?';
  if (!rows[key]) rows[key] = { n: 0, res: {}, tool: 0, fuga: 0, falla: {} };
  const o = rows[key]; o.n++; o.res[r] = (o.res[r] || 0) + 1; if (llam) o.tool++; if (fuga) o.fuga++;
  fall.forEach(f => o.falla[f] = (o.falla[f] || 0) + 1);
}
for (const [k, v] of Object.entries(rows)) console.log(k, JSON.stringify(v));

